"use client";
import React, { Suspense, useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

// ── Lazy background imports ──
const ParticleField = React.lazy(() =>
  import("@/components/flexui/particle-field").then((m) => ({ default: m.ParticleField }))
);
const GridPattern = React.lazy(() =>
  import("@/components/flexui/grid-pattern").then((m) => ({ default: m.GridPattern }))
);
const StarsBackground = React.lazy(() =>
  import("@/components/flexui/stars-background").then((m) => ({ default: m.StarsBackground }))
);
const AuroraBackground = React.lazy(() =>
  import("@/components/flexui/aurora-background").then((m) => ({ default: m.AuroraBackground }))
);

interface CinematicHeroProps {
  /** Main headline */
  headline: string;
  /** Subtitle text */
  subtitle?: string;
  /** Background variant */
  background?: "particles" | "grid" | "stars" | "aurora" | "none";
  /** Primary CTA */
  primaryCta?: { label: string; href: string };
  /** Secondary CTA */
  secondaryCta?: { label: string; href: string };
  /** Badge text */
  badge?: string;
  className?: string;
  children?: React.ReactNode;
}

// ── Word blur-reveal animation (inline) ────────────────────────
function AnimatedHeadline({ text }: { text: string }) {
  const words = useMemo(() => text.split(" "), [text]);

  return (
    <h1 className="text-5xl font-bold tracking-tight text-white sm:text-6xl md:text-7xl lg:text-8xl">
      {words.map((word, i) => (
        <motion.span
          key={`${word}-${i}`}
          className="mr-[0.25em] inline-block"
          initial={{ opacity: 0, filter: "blur(12px)", y: 20 }}
          animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
          transition={{
            duration: 0.6,
            delay: 0.1 + i * 0.12,
            ease: [0.25, 0.46, 0.45, 0.94],
          }}
        >
          {word}
        </motion.span>
      ))}
    </h1>
  );
}

// ── Background renderer ────────────────────────────────────────
function BackgroundLayer({
  variant,
}: {
  variant: CinematicHeroProps["background"];
}) {
  switch (variant) {
    case "particles":
      return (
        <ParticleField
          className="absolute inset-0"
          count={60}
          color="rgba(139, 92, 246, 0.5)"
          maxSize={3}
          speed={0.6}
        />
      );
    case "grid":
      return (
        <GridPattern
          className="absolute inset-0"
          size={48}
          opacity={0.05}
          fade
        />
      );
    case "stars":
      return (
        <StarsBackground
          className="absolute inset-0"
          count={100}
          twinkle
          twinkleSpeed={[2, 5]}
        />
      );
    case "aurora":
      return <AuroraBackground className="absolute inset-0" speed={10} blur={120} />;
    case "none":
    default:
      return null;
  }
}

export function CinematicHero({
  headline,
  subtitle,
  background = "particles",
  primaryCta,
  secondaryCta,
  badge,
  className,
  children,
}: CinematicHeroProps) {
  const [mounted, setMounted] = useState(false);
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { setMounted(true); }, []);

  return (
    <section
      className={cn(
        "relative flex min-h-screen items-center justify-center overflow-hidden bg-zinc-950",
        className
      )}
    >
      {/* Background */}
      {mounted && (
        <Suspense fallback={null}>
          <BackgroundLayer variant={background} />
        </Suspense>
      )}

      {/* Radial vignette overlay */}
      <div
        className="pointer-events-none absolute inset-0 z-[1]"
        style={{
          background:
            "radial-gradient(ellipse at center, transparent 40%, rgba(9,9,11,0.7) 100%)",
        }}
      />

      {/* Bottom gradient fade */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 z-[1] h-48 bg-gradient-to-t from-zinc-950 to-transparent" />

      {/* Content */}
      <div className="relative z-[2] mx-auto flex max-w-5xl flex-col items-center px-6 text-center">
        {/* Badge */}
        {badge && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="mb-8 inline-flex items-center gap-2 rounded-full border border-white/[0.08] bg-white/[0.04] px-4 py-1.5 text-sm font-medium text-zinc-300 backdrop-blur-sm"
          >
            <span className="relative flex h-2 w-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-75" />
              <span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-500" />
            </span>
            {badge}
          </motion.div>
        )}

        {/* Headline with staggered word blur-reveal */}
        <AnimatedHeadline text={headline} />

        {/* Subtitle */}
        {subtitle && (
          <motion.p
            className="mt-6 max-w-2xl text-lg leading-relaxed text-zinc-400 sm:text-xl"
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.5 }}
          >
            {subtitle}
          </motion.p>
        )}

        {/* CTAs */}
        {(primaryCta || secondaryCta) && (
          <motion.div
            className="mt-10 flex flex-wrap items-center justify-center gap-4"
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.7 }}
          >
            {primaryCta && (
              <a
                href={primaryCta.href}
                className="inline-flex items-center gap-2 rounded-xl bg-white px-6 py-3 text-sm font-semibold text-zinc-950 transition-all hover:bg-zinc-200 hover:shadow-lg hover:shadow-white/10"
              >
                {primaryCta.label}
              </a>
            )}
            {secondaryCta && (
              <a
                href={secondaryCta.href}
                className="inline-flex items-center gap-2 rounded-xl border border-white/[0.1] bg-white/[0.04] px-6 py-3 text-sm font-semibold text-zinc-300 backdrop-blur-sm transition-all hover:border-white/[0.2] hover:bg-white/[0.08]"
              >
                {secondaryCta.label}
              </a>
            )}
          </motion.div>
        )}

        {/* Custom children */}
        {children}
      </div>
    </section>
  );
}

"use client";

import React, { useEffect, useMemo, useState } from "react";
import { cn } from "@/lib/utils";

interface ParticleFieldProps {
  children?: React.ReactNode;
  className?: string;
  /** Number of particles */
  count?: number;
  /** Particle color */
  color?: string;
  /** Max particle size in px */
  maxSize?: number;
  /** Animation speed multiplier */
  speed?: number;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  size: number;
  duration: number;
  delay: number;
  opacity: number;
}

// Seeded PRNG — deterministic across runs
function seed(n: number): number {
  // Use integer math to avoid floating-point SSR/client mismatch
  let h = (n * 2654435761) | 0;
  h = ((h ^ (h >>> 16)) * 2246822507) | 0;
  h = ((h ^ (h >>> 13)) * 3266489909) | 0;
  h = (h ^ (h >>> 16)) | 0;
  return (h >>> 0) / 4294967296;
}

export function ParticleField({
  children,
  className,
  count = 40,
  color = "rgba(255, 255, 255, 0.6)",
  maxSize = 4,
  speed = 1,
}: ParticleFieldProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const particles = useMemo<Particle[]>(() => {
    const result: Particle[] = [];
    for (let i = 0; i < count; i++) {
      result.push({
        id: i,
        x: seed(i * 6 + 1) * 100,
        y: seed(i * 6 + 2) * 100,
        size: seed(i * 6 + 3) * (maxSize - 1) + 1,
        duration: (seed(i * 6 + 4) * 8 + 6) / speed,
        delay: seed(i * 6 + 5) * -15,
        opacity: seed(i * 6 + 6) * 0.6 + 0.3,
      });
    }
    return result;
  }, [count, maxSize, speed]);

  return (
    <div className={cn("relative overflow-hidden", className)}>
      {/* Particle layer — only rendered on client to avoid hydration mismatch */}
      {mounted && (
        <div className="pointer-events-none absolute inset-0 z-0">
          {particles.map((p) => (
            <div
              key={p.id}
              className="absolute rounded-full animate-particle-drift"
              style={{
                left: `${Math.round(p.x * 100) / 100}%`,
                top: `${Math.round(p.y * 100) / 100}%`,
                width: `${Math.round(p.size * 10) / 10}px`,
                height: `${Math.round(p.size * 10) / 10}px`,
                backgroundColor: color,
                opacity: Math.round(p.opacity * 100) / 100,
                animationDuration: `${Math.round(p.duration * 10) / 10}s`,
                animationDelay: `${Math.round(p.delay * 10) / 10}s`,
                boxShadow: `0 0 ${Math.round(p.size * 3)}px ${Math.round(p.size)}px ${color}`,
              }}
            />
          ))}
        </div>
      )}

      {/* Content renders on top */}
      <div className="relative z-10">{children}</div>
    </div>
  );
}

"use client";
import React from "react";
import { cn } from "@/lib/utils";

interface GridPatternProps {
  children?: React.ReactNode;
  className?: string;
  /** Grid cell size in px */
  size?: number;
  /** Line color */
  color?: string;
  /** Line opacity (0-1) */
  opacity?: number;
  /** Radial fade mask from center */
  fade?: boolean;
}

export function GridPattern({
  children,
  className,
  size = 40,
  color = "rgb(255 255 255)",
  opacity = 0.06,
  fade = false,
}: GridPatternProps) {
  return (
    <div className={cn("relative overflow-hidden", className)}>
      {/* Grid lines */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage: `linear-gradient(${color} / ${opacity} 1px, transparent 1px), linear-gradient(to right, ${color} / ${opacity} 1px, transparent 1px)`,
          backgroundSize: `${size}px ${size}px`,
          ...(fade
            ? {
                maskImage:
                  "radial-gradient(ellipse at center, black 30%, transparent 70%)",
                WebkitMaskImage:
                  "radial-gradient(ellipse at center, black 30%, transparent 70%)",
              }
            : {}),
        }}
      />
      {/* Children on top */}
      <div className="relative z-10">{children}</div>
    </div>
  );
}

"use client";
import React, { useMemo } from "react";
import { cn } from "@/lib/utils";

interface StarsBackgroundProps {
  children?: React.ReactNode;
  className?: string;
  /** Number of stars */
  count?: number;
  /** Star color */
  color?: string;
  /** Enable twinkling animation */
  twinkle?: boolean;
  /** Twinkle speed range in seconds [min, max] */
  twinkleSpeed?: [number, number];
}

function seededRandom(seed: number) {
  const x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
}

export function StarsBackground({
  children,
  className,
  count = 80,
  color = "white",
  twinkle = true,
  twinkleSpeed = [1.5, 4],
}: StarsBackgroundProps) {
  const stars = useMemo(() => {
    return Array.from({ length: count }, (_, i) => {
      const r = (idx: number) => seededRandom(i * 100 + idx);
      const x = r(1) * 100;
      const y = r(2) * 100;
      const size = 1 + r(3) * 2; // 1-3px
      const opacity = 0.3 + r(4) * 0.7; // 0.3-1
      const duration =
        twinkleSpeed[0] + r(5) * (twinkleSpeed[1] - twinkleSpeed[0]);
      const delay = r(6) * duration;

      return { x, y, size, opacity, duration, delay, id: i };
    });
  }, [count, twinkleSpeed]);

  return (
    <div className={cn("relative overflow-hidden", className)}>
      {/* Stars layer */}
      <div className="pointer-events-none absolute inset-0">
        {stars.map((star) => (
          <div
            key={star.id}
            className={cn("absolute rounded-full", twinkle && "animate-star-twinkle")}
            style={{
              left: `${star.x}%`,
              top: `${star.y}%`,
              width: `${star.size}px`,
              height: `${star.size}px`,
              backgroundColor: color,
              opacity: star.opacity,
              ...(twinkle
                ? {
                    animationDuration: `${star.duration}s`,
                    animationDelay: `${star.delay}s`,
                  }
                : {}),
            }}
          />
        ))}
      </div>
      {/* Content */}
      <div className="relative z-10">{children}</div>
    </div>
  );
}

"use client";

import React from "react";
import { cn } from "@/lib/utils";

interface AuroraBackgroundProps {
  children?: React.ReactNode;
  className?: string;
  /** Aurora band colors */
  colors?: string[];
  /** Animation speed in seconds */
  speed?: number;
  /** Blur amount for the aurora bands */
  blur?: number;
  /** Show the effect */
  showAurora?: boolean;
}

export function AuroraBackground({
  children,
  className,
  colors = [
    "rgba(139, 92, 246, 0.3)",
    "rgba(6, 182, 212, 0.3)",
    "rgba(16, 185, 129, 0.3)",
    "rgba(236, 72, 153, 0.3)",
  ],
  speed = 8,
  blur = 100,
  showAurora = true,
}: AuroraBackgroundProps) {
  return (
    <div
      className={cn(
        "relative overflow-hidden bg-zinc-950",
        className
      )}
    >
      {showAurora && (
        <div className="pointer-events-none absolute inset-0">
          {/* Band 1 — top-left drift */}
          <div
            className="absolute -left-1/4 -top-1/4 h-[60%] w-[80%] animate-aurora-shift rounded-full mix-blend-screen"
            style={{
              background: `radial-gradient(ellipse at center, ${colors[0] ?? "rgba(139,92,246,0.3)"}, transparent 70%)`,
              filter: `blur(${blur}px)`,
              animationDuration: `${speed}s`,
            }}
          />
          {/* Band 2 — top-right drift (reversed) */}
          <div
            className="absolute -right-1/4 -top-1/3 h-[50%] w-[70%] animate-aurora-shift rounded-full mix-blend-screen"
            style={{
              background: `radial-gradient(ellipse at center, ${colors[1] ?? "rgba(6,182,212,0.3)"}, transparent 70%)`,
              filter: `blur(${blur}px)`,
              animationDuration: `${speed * 1.4}s`,
              animationDirection: "reverse",
            }}
          />
          {/* Band 3 — center drift */}
          <div
            className="absolute left-1/4 top-1/4 h-[50%] w-[60%] animate-aurora-shift rounded-full mix-blend-screen"
            style={{
              background: `radial-gradient(ellipse at center, ${colors[2] ?? "rgba(16,185,129,0.3)"}, transparent 70%)`,
              filter: `blur(${blur * 1.2}px)`,
              animationDuration: `${speed * 1.8}s`,
              animationDelay: `${speed * -0.5}s`,
            }}
          />
          {/* Band 4 — bottom sweep */}
          <div
            className="absolute -bottom-1/4 left-1/3 h-[50%] w-[70%] animate-aurora-shift rounded-full mix-blend-screen"
            style={{
              background: `radial-gradient(ellipse at center, ${colors[3] ?? "rgba(236,72,153,0.3)"}, transparent 70%)`,
              filter: `blur(${blur}px)`,
              animationDuration: `${speed * 1.2}s`,
              animationDirection: "reverse",
              animationDelay: `${speed * -0.3}s`,
            }}
          />
        </div>
      )}

      {/* Content renders on top */}
      <div className="relative z-10">{children}</div>
    </div>
  );
}
